const voiceLiveTaskCoordinatedBy = `-- name: VoiceLiveTaskCoordinatedBy :one
SELECT EXISTS(
  SELECT 1 FROM task_meta_callbacks callback
  JOIN work_items item ON item.id=callback.task_id AND item.task_execution_generation=callback.generation
  WHERE callback.task_id=$1::text AND callback.tenant_id=$2::text
    AND callback.coordinator_actor_id=$3::text AND item.archived_at IS NULL
)::boolean
`

type VoiceLiveTaskCoordinatedByParams struct {
	TaskID             string `json:"task_id"`
	TenantID           string `json:"tenant_id"`
	CoordinatorActorID string `json:"coordinator_actor_id"`
}

func (q *Queries) VoiceLiveTaskCoordinatedBy(ctx context.Context, arg VoiceLiveTaskCoordinatedByParams) (bool, error) {
	row := q.db.QueryRow(ctx, voiceLiveTaskCoordinatedBy, arg.TaskID, arg.TenantID, arg.CoordinatorActorID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
